288→// filterToUncommittedFiles removes files from the list that are already committed to HEAD
289→// with matching content. This prevents re-adding files that an agent committed mid-turn
290→// (already condensed by PostCommit) back to FilesTouched via SaveStep. Files not in
291→// HEAD or with different content in the working tree are kept. Fails open: if any git
292→// operation errors, returns the original list unchanged.
293→func filterToUncommittedFiles(ctx context.Context, files []string, repoRoot string) []string {
294→	logCtx := logging.WithComponent(ctx, "filter-uncommitted")
295→
296→	if len(files) == 0 {
297→		return files
298→	}
299→
300→	repo, err := openRepository(ctx)
301→	if err != nil {
302→		logging.Debug(logCtx, "openRepository failed, returning all files",
303→			slog.String("error", err.Error()))
304→		return files // fail open
305→	}
306→
307→	head, err := repo.Head()
308→	if err != nil {
309→		logging.Debug(logCtx, "repo.Head() failed, returning all files",
310→			slog.String("error", err.Error()))
311→		return files // fail open (empty repo, detached HEAD, etc.)
312→	}
313→
314→	commit, err := repo.CommitObject(head.Hash())
315→	if err != nil {
316→		logging.Debug(logCtx, "repo.CommitObject failed, returning all files",
317→			slog.String("error", err.Error()),
318→			slog.String("head", head.Hash().String()))
319→		return files // fail open
320→	}
321→
322→	headTree, err := commit.Tree()
323→	if err != nil {
324→		logging.Debug(logCtx, "commit.Tree() failed, returning all files",
325→			slog.String("error", err.Error()))
326→		return files // fail open
327→	}
328→
329→	logging.Debug(logCtx, "checking files against HEAD",
330→		slog.String("head", head.Hash().String()[:7]),
331→		slog.Int("candidates", len(files)))
332→
333→	var result []string
334→	for _, relPath := range files {
335→		headFile, err := headTree.File(relPath)
336→		if err != nil {
337→			// File not in HEAD — it's uncommitted
338→			logging.Debug(logCtx, "file not in HEAD tree, keeping",
339→				slog.String("file", relPath),
340→				slog.String("error", err.Error()))
341→			result = append(result, relPath)
342→			continue
343→		}
344→
345→		// File is in HEAD — compare content with working tree
346→		absPath := filepath.Join(repoRoot, relPath)
347→		workingContent, err := os.ReadFile(absPath) //nolint:gosec // path from controlled source
348→		if err != nil {
349→			// Can't read working tree file (deleted?) — keep it
350→			logging.Debug(logCtx, "cannot read working tree file, keeping",
351→				slog.String("file", relPath),
352→				slog.String("error", err.Error()))
353→			result = append(result, relPath)
354→			continue
355→		}
356→
357→		headContent, err := headFile.Contents()
358→		if err != nil {
359→			logging.Debug(logCtx, "cannot read HEAD blob, keeping",
360→				slog.String("file", relPath),
361→				slog.String("error", err.Error()))
362→			result = append(result, relPath)
363→			continue
364→		}
365→
366→		if string(workingContent) != headContent {
367→			// Working tree differs from HEAD — uncommitted changes
368→			logging.Debug(logCtx, "content differs from HEAD, keeping",
369→				slog.String("file", relPath),
370→				slog.Int("working_len", len(workingContent)),
371→				slog.Int("head_len", len(headContent)))
372→			result = append(result, relPath)
373→		} else {
374→			logging.Debug(logCtx, "content matches HEAD, filtering out",
375→				slog.String("file", relPath))
376→		}
377→	}
378→
379→	return result
380→}
