382→// FilterAndNormalizePaths converts absolute paths to relative and filters out
383→// infrastructure paths and paths outside the repo.
384→func FilterAndNormalizePaths(files []string, cwd string) []string {
385→	var result []string
386→	for _, file := range files {
387→		relPath := paths.ToRelativePath(file, cwd)
388→		if relPath == "" {
389→			continue // outside repo
390→		}
391→		if paths.IsInfrastructurePath(relPath) {
392→			continue // skip .entire directory
393→		}
394→		result = append(result, filepath.ToSlash(relPath))
395→	}
396→	return result
397→}
