399→// mergeUnique appends elements from extra into base, skipping duplicates already in base.
400→func mergeUnique(base, extra []string) []string {
401→	if len(extra) == 0 {
402→		return base
403→	}
404→	seen := make(map[string]bool, len(base))
405→	for _, s := range base {
406→		seen[s] = true
407→	}
408→	for _, s := range extra {
409→		if !seen[s] {
410→			seen[s] = true
411→			base = append(base, s)
412→		}
413→	}
414→	return base
415→}
