441→	if err != nil {
442→		return nil, err //nolint:wrapcheck // already present in codebase
443→	}
444→
445→	untrackedFiles := []string{}
446→	for file, st := range status {
447→		if st.Worktree == git.Untracked {
448→			// Exclude .entire directory
449→			if !paths.IsInfrastructurePath(file) {
450→				untrackedFiles = append(untrackedFiles, file)
451→			}
452→		}
453→	}
454→
455→	return untrackedFiles, nil
456→}
