458→// PreTaskState stores the state captured before a task execution
459→type PreTaskState struct {
460→	ToolUseID      string   `json:"tool_use_id"`
461→	Timestamp      string   `json:"timestamp"`
462→	UntrackedFiles []string `json:"untracked_files"`
463→}
