477→// CapturePreTaskState captures current untracked files before a Task execution
478→// and saves them to a state file.
479→// Works correctly from any subdirectory within the repository.
480→func CapturePreTaskState(ctx context.Context, toolUseID string) error {
481→	if toolUseID == "" {
482→		return errors.New("tool_use_id is required")
483→	}
484→
485→	if err := validation.ValidateToolUseID(toolUseID); err != nil {
486→		return fmt.Errorf("invalid tool use ID for pre-task state: %w", err)
487→	}
488→
489→	// Get absolute path for tmp directory
490→	tmpDirAbs := resolveTmpDir(ctx)
491→
492→	// Create tmp directory if it doesn't exist
493→	if err := os.MkdirAll(tmpDirAbs, 0o750); err != nil {
494→		return fmt.Errorf("failed to create tmp directory: %w", err)
495→	}
496→
497→	// Get list of untracked files (excluding .entire directory itself)
498→	untrackedFiles, err := getUntrackedFilesForState(ctx)
499→	if err != nil {
500→		return fmt.Errorf("failed to get untracked files: %w", err)
501→	}
502→
503→	// Create state file using os.Root for traversal-resistant write
504→	state := PreTaskState{
505→		ToolUseID:      toolUseID,
506→		Timestamp:      time.Now().UTC().Format(time.RFC3339),
507→		UntrackedFiles: untrackedFiles,
508→	}
509→
510→	data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
511→	if err != nil {
512→		return fmt.Errorf("failed to marshal state: %w", err)
513→	}
514→
515→	fileName := fmt.Sprintf("pre-task-%s.json", toolUseID)
516→	root, err := os.OpenRoot(tmpDirAbs)
517→	if err != nil {
518→		return fmt.Errorf("failed to open tmp directory root: %w", err)
519→	}
520→	defer root.Close()
521→
522→	if err := osroot.WriteFile(root, fileName, data, 0o600); err != nil {
523→		return fmt.Errorf("failed to write state file: %w", err)
524→	}
525→
526→	logging.Debug(logging.WithComponent(ctx, "state"), "captured state before task",
527→		slog.Int("untracked_files", len(untrackedFiles)))
528→	return nil
529→}
