533→func LoadPreTaskState(ctx context.Context, toolUseID string) (*PreTaskState, error) {
534→	if err := validation.ValidateToolUseID(toolUseID); err != nil {
535→		return nil, fmt.Errorf("invalid tool use ID for pre-task state: %w", err)
536→	}
537→
538→	tmpDirAbs := resolveTmpDir(ctx)
539→
540→	root, err := os.OpenRoot(tmpDirAbs)
541→	if err != nil {
542→		if os.IsNotExist(err) {
543→			return nil, nil //nolint:nilnil // already present in codebase
544→		}
545→		return nil, fmt.Errorf("failed to open tmp directory root: %w", err)
546→	}
547→	defer root.Close()
548→
549→	fileName := fmt.Sprintf("pre-task-%s.json", toolUseID)
550→	data, err := osroot.ReadFile(root, fileName)
551→	if err != nil {
