587→// preTaskFilePrefix is the prefix for pre-task state files
588→const preTaskFilePrefix = "pre-task-"
589→
590→// FindActivePreTaskFile finds an active pre-task file in .entire/tmp/ and returns
591→// the parent Task's tool_use_id. Returns ("", false) if no pre-task file exists.
592→// When multiple pre-task files exist (nested subagents), returns the most recently
593→// modified one.
594→// Works correctly from any subdirectory within the repository.
595→func FindActivePreTaskFile(ctx context.Context) (taskToolUseID string, found bool) {
596→	tmpDirAbs := resolveTmpDir(ctx)
597→	entries, err := os.ReadDir(tmpDirAbs)
598→	if err != nil {
599→		return "", false
600→	}
601→
602→	var latestFile string
603→	var latestTime time.Time
604→
605→	for _, entry := range entries {
606→		if entry.IsDir() {
607→			continue
608→		}
609→		name := entry.Name()
610→		if !strings.HasPrefix(name, preTaskFilePrefix) || !strings.HasSuffix(name, ".json") {
611→			continue
612→		}
613→
614→		// Check modification time for nested subagent handling
615→		info, err := entry.Info()
616→		if err != nil {
617→			continue
618→		}
619→		if latestFile == "" || info.ModTime().After(latestTime) {
620→			latestFile = name
621→			latestTime = info.ModTime()
622→		}
623→	}
624→
625→	if latestFile == "" {
626→		return "", false
627→	}
628→
629→	// Extract tool_use_id from filename: pre-task-<tool_use_id>.json
630→	toolUseID := strings.TrimPrefix(latestFile, preTaskFilePrefix)
631→	toolUseID = strings.TrimSuffix(toolUseID, ".json")
632→	return toolUseID, true
633→}
