635→// GetNextCheckpointSequence returns the next sequence number for incremental checkpoints.
636→// It counts existing checkpoint files in the task metadata checkpoints directory.
637→// Returns 1 if no checkpoints exist yet.
638→func GetNextCheckpointSequence(sessionID, taskToolUseID string) int {
639→	// Use the session ID directly as the metadata directory name
640→	sessionMetadataDir := paths.SessionMetadataDirFromSessionID(sessionID)
641→	taskMetadataDir := strategy.TaskMetadataDir(sessionMetadataDir, taskToolUseID)
642→	checkpointsDir := filepath.Join(taskMetadataDir, "checkpoints")
643→
644→	entries, err := os.ReadDir(checkpointsDir)
645→	if err != nil {
646→		// Directory doesn't exist or can't be read - start at 1
647→		return 1
648→	}
649→
650→	// Count JSON files (checkpoints)
651→	count := 0
652→	for _, entry := range entries {
653→		if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".json") {
654→			count++
655→		}
656→	}
657→
658→	return count + 1
659→}
