 31→// GitAuthor represents the git user configuration
 32→type GitAuthor struct {
 33→	Name  string
 34→	Email string
 35→}
 36→
 37→// GetGitAuthor retrieves the git user.name and user.email from the repository config.
 38→// It checks local config first, then falls back to global config.
 39→// If go-git can't find the config, it falls back to using the git command.
 40→// Returns fallback defaults if no user is configured anywhere.
 41→func GetGitAuthor(ctx context.Context) (*GitAuthor, error) {
 42→	repo, err := openRepository(ctx)
 43→	if err != nil {
 44→		return nil, fmt.Errorf("failed to open git repository: %w", err)
 45→	}
 46→
 47→	name, email := strategy.GetGitAuthorFromRepo(repo)
 48→
 49→	// If go-git returned defaults, try using git command as fallback
 50→	// This handles cases where go-git can't find the config (e.g., different HOME paths,
 51→	// non-standard config locations, or environment issues in hook contexts)
 52→	if name == "Unknown" {
 53→		if gitName := getGitConfigValue(ctx, "user.name"); gitName != "" {
 54→			name = gitName
 55→		}
 56→	}
 57→	if email == "unknown@local" {
 58→		if gitEmail := getGitConfigValue(ctx, "user.email"); gitEmail != "" {
 59→			email = gitEmail
 60→		}
 61→	}
 62→
 63→	return &GitAuthor{
 64→		Name:  name,
 65→		Email: email,
 66→	}, nil
 67→}
 68→
 69→// getGitConfigValue retrieves a git config value using the git command.
 70→// Returns empty string if the value is not set or on error.
 71→func getGitConfigValue(ctx context.Context, key string) string {
 72→	cmd := exec.CommandContext(ctx, "git", "config", "--get", key)
 73→	output, err := cmd.Output()
 74→	if err != nil {
 75→		return ""
 76→	}
 77→	return strings.TrimSpace(string(output))
 78→}
 79→
 80→// IsOnDefaultBranch checks if the repository is currently on the default branch.
 81→// It determines the default branch by:
 82→// 1. Checking the remote origin's HEAD reference
 83→// 2. Falling back to common names (main, master) if remote HEAD is unavailable
 84→// Returns (isDefault, branchName, error)
 85→func IsOnDefaultBranch(ctx context.Context) (bool, string, error) {
 86→	repo, err := openRepository(ctx)
 87→	if err != nil {
 88→		return false, "", fmt.Errorf("failed to open git repository: %w", err)
 89→	}
 90→
 91→	// Get current branch
 92→	head, err := repo.Head()
 93→	if err != nil {
 94→		return false, "", fmt.Errorf("failed to get HEAD: %w", err)
 95→	}
 96→
 97→	if !head.Name().IsBranch() {
 98→		// Detached HEAD - not on any branch
 99→		return false, "", nil
100→	}

