 65→	if os.Getenv("CI") == "" {
 66→		return nil
 67→	}
 68→	apiKey := os.Getenv("ANTHROPIC_API_KEY")
 69→	if apiKey == "" {
 70→		return nil
 71→	}
 72→	home, err := os.UserHomeDir()
 73→	if err != nil {
 74→		return fmt.Errorf("get home dir: %w", err)
 75→	}
 76→	dir := filepath.Join(home, ".claude")
 77→	if err := os.MkdirAll(dir, 0o755); err != nil {
 78→		return fmt.Errorf("mkdir %s: %w", dir, err)
 79→	}
 80→	config := fmt.Sprintf(`{"primaryApiKey":%q,"hasCompletedOnboarding":true}`, apiKey)
 81→	path := filepath.Join(dir, ".claude.json")
 82→	return os.WriteFile(path, []byte(config), 0o644)
 83→}
