 85→func (c *Claude) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
 86→	cfg := &runConfig{Model: "haiku"}
 87→	for _, o := range opts {
 88→		o(cfg)
 89→	}
 90→
 91→	configDir, err := cleanConfigDir()
 92→	if err != nil {
 93→		return Output{}, fmt.Errorf("create clean config dir: %w", err)
 94→	}
 95→	defer func() { _ = os.RemoveAll(configDir) }()
 96→
 97→	env := append(cleanEnv(),
 98→		"ACCESSIBLE=1",
 99→
100→		// See https://code.claude.com/docs/en/settings - without this setting Claude was going off and
101→		// trying to Git-clone its plugin marketplace, which meant calling git commands that could fail
102→		// due to a user's exotic config (e.g. in paul's case, needing SSH-keychain access granted every
103→		// time).  That's no good, so for the E2E tests, we tell Claude not to make calls to auto-update
104→		// itself, clone its plugins, etc.
105→		"CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC=1",
106→		"CLAUDE_CONFIG_DIR="+configDir,
107→	)
108→
109→	args := []string{"-p", prompt, "--model", cfg.Model, "--dangerously-skip-permissions"}
110→	displayArgs := []string{"-p", fmt.Sprintf("%q", prompt), "--model", cfg.Model, "--dangerously-skip-permissions"}
111→	cmd := exec.CommandContext(ctx, c.Binary(), args...)
112→	cmd.Dir = dir
113→	cmd.Stdin = nil
114→	cmd.Env = env
115→	setupProcessGroup(cmd)
116→	cmd.WaitDelay = 5 * time.Second
117→
118→	var stdout, stderr strings.Builder
119→	cmd.Stdout = &stdout
120→	cmd.Stderr = &stderr
121→
122→	err = cmd.Run()
123→	exitCode := 0
124→	if err != nil {
125→		exitErr := &exec.ExitError{}
126→		if errors.As(err, &exitErr) {
127→			exitCode = exitErr.ExitCode()
128→		} else {
129→			exitCode = -1
130→		}
131→	}
132→
133→	return Output{
134→		Command:  c.Binary() + " " + strings.Join(displayArgs, " "),
135→		Stdout:   stdout.String(),
136→		Stderr:   stderr.String(),
137→		ExitCode: exitCode,
138→	}, err
139→}
