141→func (c *Claude) StartSession(ctx context.Context, dir string) (Session, error) {
142→	if runtime.GOOS == "windows" {
143→		return nil, nil //nolint:nilnil // nil session signals "not supported" per Agent interface contract
144→	}
145→	name := fmt.Sprintf("claude-test-%d", time.Now().UnixNano())
146→
147→	configDir, err := cleanConfigDir()
148→	if err != nil {
149→		return nil, fmt.Errorf("create clean config dir: %w", err)
150→	}
151→
152→	envArgs := []string{
153→		"ACCESSIBLE=1",
154→
155→		// See https://code.claude.com/docs/en/settings - without this setting Claude was going off and
156→		// trying to Git-clone its plugin marketplace, which meant calling git commands that could fail
157→		// due to a user's exotic config (e.g. in paul's case, needing SSH-keychain access granted every
158→		// time).  That's no good, so for the E2E tests, we tell Claude not to make calls to auto-update
159→		// itself, clone its plugins, etc.
160→		"CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC=1",
161→		"CLAUDE_CONFIG_DIR=" + configDir,
162→	}
163→
164→	args := append([]string{"env"}, envArgs...)
165→	args = append(args, c.Binary(), "--dangerously-skip-permissions")
166→	s, err := NewTmuxSession(name, dir, []string{"CLAUDECODE", "ENTIRE_TEST_TTY"}, args[0], args[1:]...)
167→	if err != nil {
168→		_ = os.RemoveAll(configDir)
169→		return nil, err
170→	}
171→	s.OnClose(func() { _ = os.RemoveAll(configDir) })
172→
173→	// Dismiss startup dialogs until we reach the input prompt.
174→	for range 5 {
175→		content, err := s.WaitFor(`❯`, 15*time.Second)
176→		if err != nil {
177→			_ = s.Close()
178→			return nil, fmt.Errorf("waiting for startup prompt: %w", err)
179→		}
180→		if !strings.Contains(content, "Enter to confirm") {
181→			break
182→		}
183→		// The bypass permissions dialog defaults to "No, exit" —
184→		// arrow down to "Yes, I accept" before confirming.
185→		if strings.Contains(content, "Yes, I accept") {
186→			_ = s.SendKeys("Down")
187→			time.Sleep(200 * time.Millisecond)
188→		}
189→		_ = s.SendKeys("Enter")
190→		time.Sleep(500 * time.Millisecond)
191→	}
192→	s.stableAtSend = ""
193→
194→	return s, nil
195→}
