197→// cleanConfigDir creates an isolated temp directory for CLAUDE_CONFIG_DIR so
198→// that E2E test runs don't inherit any user settings (CLAUDE.md, skills,
199→// projects, plugins, etc.).
200→func cleanConfigDir() (string, error) {
201→	dst, err := os.MkdirTemp("", "claude-config-*")
202→	if err != nil {
203→		return "", err
204→	}
205→
206→	if os.Getenv("CI") != "" {
207→		if home, err := os.UserHomeDir(); err == nil {
208→			src := filepath.Join(home, ".claude", ".claude.json")
209→			if _, err := os.Stat(src); err == nil {
210→				_ = linkFile(src, filepath.Join(dst, ".claude.json"))
211→			}
212→		}
213→	} else {
214→		_ = os.WriteFile(filepath.Join(dst, ".claude.json"),
215→			[]byte(`{"hasCompletedOnboarding":true}`), 0o644)
216→	}
217→
218→	return dst, nil
219→}
