118→// ReadSession reads a session from Claude's storage (JSONL transcript file).
119→// The session data is stored in NativeData as raw JSONL bytes.
120→// ModifiedFiles is computed by parsing the transcript.
121→func (c *ClaudeCodeAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
122→	if input.SessionRef == "" {
123→		return nil, errors.New("session reference (transcript path) is required")
124→	}
125→
126→	// Read the raw JSONL file
127→	data, err := os.ReadFile(input.SessionRef)
128→	if err != nil {
129→		return nil, fmt.Errorf("failed to read transcript: %w", err)
130→	}
131→
132→	// Parse to extract computed fields
133→	lines, err := transcript.ParseFromBytes(data)
134→	if err != nil {
135→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
136→	}
137→
138→	return &agent.AgentSession{
139→		SessionID:     input.SessionID,
140→		AgentName:     c.Name(),
141→		SessionRef:    input.SessionRef,
142→		StartTime:     time.Now(),
143→		NativeData:    data,
144→		ModifiedFiles: ExtractModifiedFiles(lines),
145→	}, nil
146→}
