148→// WriteSession writes a session to Claude's storage (JSONL transcript file).
149→// Uses the NativeData field which contains raw JSONL bytes.
150→// The session must have been created by Claude Code (AgentName check).

150→// The session must have been created by Claude Code (AgentName check).
151→func (c *ClaudeCodeAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
152→	if session == nil {
153→		return errors.New("session is nil")
154→	}
155→
156→	// Verify this session belongs to Claude Code
157→	if session.AgentName != "" && session.AgentName != c.Name() {
158→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
159→	}
160→
161→	if session.SessionRef == "" {
162→		return errors.New("session reference (transcript path) is required")
163→	}
164→
165→	if len(session.NativeData) == 0 {
166→		return errors.New("session has no native data to write")
167→	}
168→
169→	// Write the raw JSONL data
170→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
171→		return fmt.Errorf("failed to write transcript: %w", err)
172→	}
173→
174→	return nil
175→}
