183→
184→// TruncateAtUUID returns a new session truncated at the given UUID (inclusive).
185→// This is used for rewind operations to restore transcript state.
186→// Requires NativeData to be populated.
187→func (c *ClaudeCodeAgent) TruncateAtUUID(session *agent.AgentSession, uuid string) (*agent.AgentSession, error) {
188→	if session == nil {
189→		return nil, errors.New("session is nil")
190→	}
191→
192→	if len(session.NativeData) == 0 {
193→		return nil, errors.New("session has no native data")
194→	}
195→
196→	if uuid == "" {
197→		// No truncation needed, return copy
198→		return &agent.AgentSession{
199→			SessionID:     session.SessionID,
200→			AgentName:     session.AgentName,
201→			RepoPath:      session.RepoPath,
202→			SessionRef:    session.SessionRef,
203→			StartTime:     session.StartTime,
204→			NativeData:    session.NativeData,
205→			ModifiedFiles: session.ModifiedFiles,
206→		}, nil
207→	}
208→
209→	// Parse, truncate, re-serialize
210→	lines, err := transcript.ParseFromBytes(session.NativeData)
211→	if err != nil {
212→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
213→	}
214→
215→	truncated := TruncateAtUUID(lines, uuid)
216→
217→	newData, err := SerializeTranscript(truncated)
218→	if err != nil {
219→		return nil, fmt.Errorf("failed to serialize truncated transcript: %w", err)
220→	}
221→
222→	return &agent.AgentSession{
223→		SessionID:     session.SessionID,
224→		AgentName:     session.AgentName,
225→		RepoPath:      session.RepoPath,
226→		SessionRef:    session.SessionRef,
227→		StartTime:     session.StartTime,
228→		NativeData:    newData,
229→		ModifiedFiles: ExtractModifiedFiles(truncated),
230→	}, nil
231→}
