495→// --- Transcript ---
496→
497→func setupTranscript(sessionID string) string {
498→	home, err := os.UserHomeDir()
499→	if err != nil {
500→		fatal("home dir: %v", err)
501→	}
502→	transcriptDir := filepath.Join(home, ".vogon", "sessions")
503→	if err := os.MkdirAll(transcriptDir, 0o755); err != nil {
504→		fatal("mkdir transcript dir: %v", err)
505→	}
506→	path := filepath.Join(transcriptDir, sessionID+".jsonl")
507→	// Create empty file
508→	if err := os.WriteFile(path, nil, 0o644); err != nil {
509→		fatal("create transcript: %v", err)
510→	}
511→	return path
512→}
513→
514→type transcriptEntry struct {
515→	Type      string `json:"type"`
516→	Timestamp string `json:"timestamp"`
517→	Message   string `json:"message"`
518→}
519→
520→func appendTranscript(path, role, content string) {
521→	entry := transcriptEntry{
522→		Type:      role,
523→		Timestamp: time.Now().Format(time.RFC3339),
524→		Message:   content,
525→	}
526→	data, _ := json.Marshal(entry) //nolint:errchkjson // transcriptEntry has no unsafe types
527→	data = append(data, '\n')
528→
529→	f, err := os.OpenFile(path, os.O_APPEND|os.O_WRONLY|os.O_CREATE, 0o644)
530→	if err != nil {
531→		return
532→	}
533→	defer f.Close()
534→	f.Write(data)
535→}
