 10→func TestIsSubpath(t *testing.T) {
 11→	tests := []struct {
 12→		name   string
 13→		parent string
 14→		child  string
 15→		want   bool
 16→	}{
 17→		// Basic containment
 18→		{name: "child inside parent", parent: "/a/b", child: "/a/b/c", want: true},
 19→		{name: "equal paths", parent: "/a/b", child: "/a/b", want: true},
 20→		{name: "child outside parent", parent: "/a/b", child: "/a/c", want: false},
 21→		{name: "parent prefix but not subpath", parent: "/a/b", child: "/a/bc", want: false},
 22→
 23→		// Traversal attacks
 24→		{name: "dot-dot escape", parent: "/a/b", child: "/a/b/../../../etc/passwd", want: false},
 25→		{name: "dot-dot at end", parent: "/a/b", child: "/a/b/..", want: false},
 26→		{name: "dot-dot in middle", parent: "/a/b/c", child: "/a/b/c/../../d", want: false},
 27→
 28→		// Relative paths
 29→		{name: "relative child inside", parent: ".entire", child: ".entire/metadata/test", want: true},
 30→		{name: "relative equal", parent: ".entire", child: ".entire", want: true},
 31→		{name: "relative outside", parent: ".entire", child: "src/main.go", want: false},
 32→		{name: "relative prefix not subpath", parent: ".entire", child: ".entirefile", want: false},
 33→
 34→		// Edge cases
 35→		{name: "root parent", parent: "/", child: "/anything", want: true},
 36→		{name: "dot current dir", parent: ".", child: "foo/bar", want: true},
 37→	}
 38→
 39→	for _, tt := range tests {
 40→		t.Run(tt.name, func(t *testing.T) {
 41→			got := IsSubpath(tt.parent, tt.child)
 42→			if got != tt.want {
 43→				t.Errorf("IsSubpath(%q, %q) = %v, want %v", tt.parent, tt.child, got, tt.want)
 44→			}
 45→		})
 46→	}
 47→}
