 25→// PrePromptState stores the state captured before a user prompt
 26→type PrePromptState struct {
 27→	SessionID      string   `json:"session_id"`
 28→	Timestamp      string   `json:"timestamp"`
 29→	UntrackedFiles []string `json:"untracked_files"`
 30→
 31→	// TranscriptOffset is the unified transcript position when this state was captured.
 32→	// For Claude Code (JSONL), this is the line count.
 33→	// For Gemini CLI (JSON), this is the message count.
 34→	// Zero means not set or session just started.
 35→	TranscriptOffset int `json:"transcript_offset,omitempty"`
 36→
 37→	// LastTranscriptIdentifier is the agent-specific identifier at the transcript position.
 38→	// UUID for Claude Code, message ID for Gemini CLI. Optional metadata.
 39→	LastTranscriptIdentifier string `json:"last_transcript_identifier,omitempty"`
 40→
 41→	// Deprecated: StartMessageIndex is the old Gemini-specific field.
 42→	// Migrated to TranscriptOffset on load.
 43→	StartMessageIndex int `json:"start_message_index,omitempty"`
 44→
 45→	// Deprecated: StepTranscriptStart is the old Claude-specific field.
 46→	// Migrated to TranscriptOffset on load.
 47→	StepTranscriptStart int `json:"step_transcript_start,omitempty"`
 48→
 49→	// Deprecated: LastTranscriptLineCount is the oldest name for transcript position.
 50→	// Migrated to TranscriptOffset on load.
 51→	LastTranscriptLineCount int `json:"last_transcript_line_count,omitempty"`
 52→}
 53→
 54→// PreUntrackedFiles returns the untracked files list, or nil if the receiver is nil.
 55→// This nil-vs-empty distinction lets DetectFileChanges know whether to skip new-file detection.
 56→// When the receiver is non-nil but UntrackedFiles is nil (e.g., old state files deserialized with
 57→// "untracked_files": null), returns an empty non-nil slice so that all current untracked files
 58→// are correctly treated as new.
 59→func (s *PrePromptState) PreUntrackedFiles() []string {
 60→	if s == nil {
 61→		return nil
 62→	}
 63→	if s.UntrackedFiles == nil {
 64→		return []string{}
 65→	}
 66→	return s.UntrackedFiles
 67→}
 68→
 69→// normalizePrePromptState migrates deprecated fields after loading from JSON.
 70→func (s *PrePromptState) normalizePrePromptState() {
 71→	// Migrate the oldest field to the intermediate field first
 72→	if s.StepTranscriptStart == 0 && s.LastTranscriptLineCount > 0 {
 73→		s.StepTranscriptStart = s.LastTranscriptLineCount
 74→	}
 75→	s.LastTranscriptLineCount = 0
 76→
 77→	// Migrate all deprecated fields to the unified TranscriptOffset
 78→	if s.TranscriptOffset == 0 {
 79→		if s.StepTranscriptStart > 0 {
 80→			s.TranscriptOffset = s.StepTranscriptStart
 81→		} else if s.StartMessageIndex > 0 {
 82→			s.TranscriptOffset = s.StartMessageIndex
 83→		}
 84→	}
 85→	s.StepTranscriptStart = 0
 86→	s.StartMessageIndex = 0
 87→}
 88→
 89→// CapturePrePromptState captures current untracked files and transcript position before a prompt
 90→// and saves them to a state file.
 91→//
 92→// The agent parameter is used to determine the transcript position via TranscriptAnalyzer.
 93→// If the agent does not implement TranscriptAnalyzer, the transcript offset will be 0.
 94→// The sessionRef parameter is optional — if empty, transcript position won't be captured.
 95→//
 96→// Works correctly from any subdirectory within the repository.
 97→func CapturePrePromptState(ctx context.Context, ag agent.Agent, sessionID, sessionRef string) error {
 98→	if sessionID == "" {
 99→		sessionID = unknownSessionID
100→	}
101→
102→	if err := validation.ValidateSessionID(sessionID); err != nil {
103→		return fmt.Errorf("invalid session ID for pre-prompt state: %w", err)
104→	}
105→
106→	// Get absolute path for tmp directory
107→	tmpDirAbs := resolveTmpDir(ctx)
108→
109→	// Create tmp directory if it doesn't exist
110→	if err := os.MkdirAll(tmpDirAbs, 0o750); err != nil {
111→		return fmt.Errorf("failed to create tmp directory: %w", err)
112→	}
113→
114→	// Get list of untracked files (excluding .entire directory itself)
115→	untrackedFiles, err := getUntrackedFilesForState(ctx)
116→	if err != nil {
117→		return fmt.Errorf("failed to get untracked files: %w", err)
118→	}
119→
120→	// Get transcript position using TranscriptAnalyzer if available
121→	var transcriptOffset int
