288→// filterToUncommittedFiles removes files from the list that are already committed to HEAD
289→// with matching content. This prevents re-adding files that an agent committed mid-turn
290→// (already condensed by PostCommit) back to FilesTouched via SaveStep. Files not in
291→// HEAD or with different content in the working tree are kept. Fails open: if any git
292→// operation errors, returns the original list unchanged.
293→func filterToUncommittedFiles(ctx context.Context, files []string, repoRoot string) []string {
294→	if len(files) == 0 {
295→		return files
296→	}
297→
298→	repo, err := openRepository(ctx)
299→	if err != nil {
300→		return files // fail open
301→	}
302→
303→	head, err := repo.Head()
304→	if err != nil {
305→		return files // fail open (empty repo, detached HEAD, etc.)
306→	}
307→
308→	commit, err := repo.CommitObject(head.Hash())
309→	if err != nil {
310→		return files // fail open
311→	}
312→
313→	headTree, err := commit.Tree()
314→	if err != nil {
315→		return files // fail open
316→	}
317→
318→	logCtx := logging.WithComponent(ctx, "filter-uncommitted")
319→
320→	var result []string
321→	for _, relPath := range files {
322→		headFile, err := headTree.File(relPath)
323→		if err != nil {
324→			// File not in HEAD — it's uncommitted (or path normalization bug)
325→			logging.Debug(logCtx, "file not in HEAD tree, keeping",
326→				slog.String("file", relPath),
327→				slog.String("error", err.Error()))
328→			result = append(result, relPath)
329→			continue
330→		}
331→
332→		// File is in HEAD — compare content with working tree
333→		absPath := filepath.Join(repoRoot, relPath)
334→		workingContent, err := os.ReadFile(absPath) //nolint:gosec // path from controlled source
335→		if err != nil {
336→			// Can't read working tree file (deleted?) — keep it
337→			result = append(result, relPath)
338→			continue
339→		}
340→
341→		headContent, err := headFile.Contents()
342→		if err != nil {
343→			result = append(result, relPath)
344→			continue
345→		}
346→
347→		if string(workingContent) != headContent {
348→			// Working tree differs from HEAD — uncommitted changes
349→			result = append(result, relPath)
350→		}
351→		// else: content matches HEAD — already committed, skip
352→	}
353→
354→	return result
355→}
