610→// GetNextCheckpointSequence returns the next sequence number for incremental checkpoints.
611→// It counts existing checkpoint files in the task metadata checkpoints directory.
612→// Returns 1 if no checkpoints exist yet.
613→func GetNextCheckpointSequence(sessionID, taskToolUseID string) int {
614→	// Use the session ID directly as the metadata directory name
615→	sessionMetadataDir := paths.SessionMetadataDirFromSessionID(sessionID)
616→	taskMetadataDir := strategy.TaskMetadataDir(sessionMetadataDir, taskToolUseID)
617→	checkpointsDir := filepath.Join(taskMetadataDir, "checkpoints")
618→
619→	entries, err := os.ReadDir(checkpointsDir)
620→	if err != nil {
621→		// Directory doesn't exist or can't be read - start at 1
622→		return 1
623→	}
624→
625→	// Count JSON files (checkpoints)
626→	count := 0
627→	for _, entry := range entries {
628→		if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".json") {
629→			count++
630→		}
631→	}
632→
633→	return count + 1
634→}
