 33→// SetupRepo creates a fresh git repository in a temporary directory, seeds it
 34→// with an initial commit, and runs `entire enable` for the given agent.
 35→// Artifact capture is registered as a cleanup function.
 36→//
 37→// When E2E_KEEP_REPOS is set, the temporary directory is not cleaned up
 38→// so it can be inspected after the test. A symlink in the artifact dir
 39→// points to the preserved repo.
 40→func SetupRepo(t *testing.T, agent agents.Agent) *RepoState {
 41→	t.Helper()
 42→
 43→	keepRepos := os.Getenv("E2E_KEEP_REPOS") != ""
 44→
 45→	// Always use os.MkdirTemp instead of t.TempDir(). Go's t.TempDir()
 46→	// creates nested subdirectories (TestName.../001/) whose structure
 47→	// confuses some agents' (e.g. opencode) working-directory resolution.
 48→	dir, err := os.MkdirTemp("", "e2e-repo-*")
 49→	if err != nil {
 50→		t.Fatalf("create temp dir: %v", err)
 51→	}
 52→	if keepRepos {
 53→		t.Logf("E2E_KEEP_REPOS: repo will be preserved at %s", dir)
 54→	} else {
 55→		t.Cleanup(func() { os.RemoveAll(dir) })
 56→	}
 57→
 58→	// Resolve symlinks (macOS: /var -> /private/var) so paths match
 59→	// what agent CLIs see when they resolve their own CWD.
 60→	if resolved, err := filepath.EvalSymlinks(dir); err == nil {
 61→		dir = resolved
 62→	}
 63→
 64→	Git(t, dir, "init")
 65→	Git(t, dir, "config", "user.name", "E2E Test")
 66→	Git(t, dir, "config", "user.email", "e2e@test.local")
 67→	Git(t, dir, "config", "core.pager", "cat")
 68→	Git(t, dir, "config", "core.autocrlf", "true")
 69→	Git(t, dir, "commit", "--allow-empty", "-m", "initial commit")
 70→
 71→	// External agents need external_agents enabled in settings before enable,
 72→	// so the CLI can discover the agent binary via PATH during DiscoverAndRegister.
 73→	if ea, ok := agent.(agents.ExternalAgent); ok && ea.IsExternalAgent() {
 74→		entireDir := filepath.Join(dir, ".entire")
 75→		if err := os.MkdirAll(entireDir, 0o755); err != nil {
 76→			t.Fatalf("create .entire for external agent: %v", err)
 77→		}
 78→		if err := os.WriteFile(filepath.Join(entireDir, "settings.json"),
 79→			[]byte("{\"external_agents\": true}\n"), 0o644); err != nil {
 80→			t.Fatalf("write external_agents setting: %v", err)
 81→		}
 82→	}
 83→
 84→	entire.Enable(t, dir, agent.EntireAgent())
 85→	if agent.Name() == "factoryai-droid" {
 86→		if err := configureDroidRepoSettings(dir); err != nil {
 87→			t.Fatalf("configure droid repo settings: %v", err)
 88→		}
 89→	}
 90→	// commit_linking=always ensures the prepare-commit-msg hook adds the
 91→	// Entire-Checkpoint trailer unconditionally. This is needed because
 92→	// interactive agents run inside tmux (hasTTY()=true) but can't respond to
 93→	// prompts, and content detection may fail on the first checkpoint when no
 94→	// shadow branch exists yet. Prompt-mode agents still exercise the !hasTTY()
 95→	// fast path since they have no TTY regardless of this setting.
 96→	PatchSettings(t, dir, map[string]any{"log_level": "debug", "commit_linking": "always"})
 97→
 98→	// Copilot CLI blocks on a "No copilot instructions found" notice in fresh
 99→	// repos that lack .github/copilot-instructions.md, preventing the interactive
100→	// prompt from appearing.
101→	if agent.Name() == "copilot-cli" {
102→		ghDir := filepath.Join(dir, ".github")
103→		if err := os.MkdirAll(ghDir, 0o755); err != nil {
104→			t.Fatalf("create .github dir: %v", err)
105→		}
106→		if err := os.WriteFile(filepath.Join(ghDir, "copilot-instructions.md"), []byte("# E2E Test\n"), 0o644); err != nil {
107→			t.Fatalf("write copilot-instructions.md: %v", err)
108→		}
109→	}
110→
111→	// OpenCode's non-interactive mode auto-rejects external_directory permission
112→	// since there's no user to prompt. Write a config to allow it.
113→	if agent.Name() == "opencode" {
114→		cfg := `{"$schema": "https://opencode.ai/config.json", "permission": {"external_directory": "allow"}}`
115→		if key := os.Getenv("ANTHROPIC_API_KEY"); key != "" {
116→			cfg = fmt.Sprintf(`{"$schema": "https://opencode.ai/config.json", "permission": {"external_directory": "allow"}, "provider": {"anthropic": {"options": {"apiKey": %q}}}}`, key)
117→		}
