255→	var b strings.Builder
256→	if len(data) > 0 {
257→		b.Write(data)
258→		if data[len(data)-1] != '\n' {
259→			b.WriteByte('\n')
260→		}
261→	}
262→	b.WriteString(entry)
263→	b.WriteByte('\n')
