274→// ForEachAgent runs fn as a parallel subtest for every registered agent.
275→// It handles repo setup, concurrency gating, context timeout, and cleanup.
276→// The timeout is scaled by each agent's TimeoutMultiplier.
277→//
278→// If RunPrompt detects a transient API error (e.g. rate limit, token refresh
279→// failure), it panics with errScenarioRestart. ForEachAgent recovers from the
280→// panic and restarts the entire scenario with a fresh repository, up to
281→// maxScenarioRestarts times. This avoids stale CLI session state from the
282→// failed attempt poisoning the retry.
283→func ForEachAgent(t *testing.T, timeout time.Duration, fn func(t *testing.T, s *RepoState, ctx context.Context)) {
284→	t.Helper()
285→	t.Parallel()
286→	all := agents.All()
287→	if len(all) == 0 {
288→		t.Skip("no agents registered (check E2E_AGENT filter)")
289→	}
290→	for _, agent := range all {
291→		t.Run(agent.Name(), func(t *testing.T) {
292→			// Use the global test deadline for slot wait so we don't
293→			// skip prematurely — only bail if the whole binary is dying.
294→			slotCtx := context.Background()
295→			if deadline, ok := t.Deadline(); ok {
296→				var cancel context.CancelFunc
297→				slotCtx, cancel = context.WithDeadline(slotCtx, deadline)
298→				defer cancel()
299→			}
300→			if err := agents.AcquireSlot(slotCtx, agent); err != nil {
301→				t.Fatalf("timed out waiting for agent slot: %v", err)
302→			}
303→			defer agents.ReleaseSlot(agent)
304→
305→			// Per-test timeout starts after slot is acquired, scaled
306→			// by the agent's multiplier (e.g. 2.5× for gemini).
307→			scaled := time.Duration(float64(timeout) * agent.TimeoutMultiplier())
308→
309→			var prevState *RepoState
310→			for attempt := range maxScenarioRestarts + 1 {
311→				s := SetupRepo(t, agent)
312→				ctx, cancel := context.WithTimeout(context.Background(), scaled)
313→
314→				// On restart, suppress artifact capture from the previous
315→				// failed attempt so it doesn't overwrite the final one.
316→				if prevState != nil {
317→					prevState.skipArtifacts = true
318→				}
319→
320→				restarted := runScenario(t, s, ctx, fn)
321→				cancel()
322→
323→				if !restarted {
324→					return
325→				}
326→				prevState = s
327→				if attempt >= maxScenarioRestarts {
328→					t.Fatalf("exhausted %d scenario attempts due to transient API errors", maxScenarioRestarts+1)
329→				}
330→				t.Logf("transient error, restarting scenario (attempt %d/%d)", attempt+2, maxScenarioRestarts+1)
331→			}
332→		})
333→	}
334→}
