336→// runScenario runs the test function and recovers from errScenarioRestart
337→// panics triggered by transient API errors in RunPrompt. Returns true if
338→// the scenario should be restarted with a fresh repository.
339→func runScenario(t *testing.T, s *RepoState, ctx context.Context, fn func(t *testing.T, s *RepoState, ctx context.Context)) (restarted bool) {
340→	t.Helper()
341→	defer func() {
342→		if r := recover(); r != nil {
343→			if _, ok := r.(errScenarioRestart); ok {
344→				restarted = true
345→				return
346→			}
347→			panic(r) // re-panic for unexpected panics
348→		}
349→	}()
350→	fn(t, s, ctx)
351→	return false
352→}
