214→// WaitForCheckpointExists polls until the checkpoint ID appears on the
215→// checkpoint branch and its metadata.json is readable, or fails after timeout.
216→func WaitForCheckpointExists(t *testing.T, dir string, checkpointID string, timeout time.Duration) {
217→	t.Helper()
218→	deadline := time.Now().Add(timeout)
219→	for time.Now().Before(deadline) {
