154→		return fmt.Errorf("get home dir: %w", err)
155→	}
156→
157→	globalSettingsPath := filepath.Join(home, ".factory", "settings.json")
158→	repoSettingsPath := filepath.Join(repoDir, droidRepoSettingsPath)
159→
160→	if err := mergeDroidCustomModels(globalSettingsPath, repoSettingsPath); err != nil {
161→		return err
162→	}
163→	if err := ensureGitInfoExcludeContains(repoDir, droidRepoSettingsPath); err != nil {
164→		return fmt.Errorf("exclude droid settings from git: %w", err)
165→	}
166→	return nil
167→}
