169→func mergeDroidCustomModels(globalSettingsPath, repoSettingsPath string) error {
170→	globalSettings, err := loadJSONMap(globalSettingsPath, "global droid settings")
171→	if err != nil {
172→		return err
173→	}
174→
175→	customModels, ok := globalSettings["customModels"]
176→	if !ok {
177→		return fmt.Errorf(
178→			"global droid settings at %s missing customModels; repo-local %s shadows global settings",
179→			globalSettingsPath,
180→			repoSettingsPath,
181→		)
182→	}
183→
184→	var models []json.RawMessage
185→	if err := json.Unmarshal(customModels, &models); err != nil {
186→		return fmt.Errorf("parse customModels in %s: %w", globalSettingsPath, err)
187→	}
188→	if len(models) == 0 {
189→		return fmt.Errorf("global droid settings at %s has empty customModels", globalSettingsPath)
190→	}
191→
192→	repoSettings, err := loadJSONMap(repoSettingsPath, "repo-local droid settings")
193→	if err != nil {
194→		return err
195→	}
196→	repoSettings["customModels"] = customModels
197→
198→	// Set the active custom model so interactive mode uses the BYOK model
199→	// instead of prompting for selection. The value must match the Model
200→	// field from the customModels entry (not the displayName).
201→	modelJSON, err := json.Marshal(agents.DefaultDroidModel())
202→	if err != nil {
203→		return fmt.Errorf("marshal model setting: %w", err)
204→	}
205→	repoSettings["model"] = json.RawMessage(modelJSON)
206→
207→	// High autonomy prevents Droid from asking for confirmation during
208→	// interactive E2E tests, which would cause hangs waiting for input.
209→	repoSettings["autonomyMode"] = json.RawMessage(`"auto-high"`)
210→	repoSettings["completionSound"] = json.RawMessage(`"off"`)
211→
212→	out, err := json.MarshalIndent(repoSettings, "", "  ")
213→	if err != nil {
214→		return fmt.Errorf("marshal repo-local droid settings: %w", err)
215→	}
216→	out = append(out, '\n')
217→
218→	if err := os.WriteFile(repoSettingsPath, out, 0o600); err != nil {
219→		return fmt.Errorf("write repo-local droid settings %s: %w", repoSettingsPath, err)
220→	}
221→	return nil
222→}
