224→func loadJSONMap(path, description string) (map[string]json.RawMessage, error) {
225→	data, err := os.ReadFile(path)
226→	if err != nil {
227→		return nil, fmt.Errorf("read %s at %s: %w", description, path, err)
228→	}
229→
230→	var parsed map[string]json.RawMessage
231→	if err := json.Unmarshal(data, &parsed); err != nil {
232→		return nil, fmt.Errorf("parse %s at %s: %w", description, path, err)
233→	}
234→	if parsed == nil {
235→		parsed = make(map[string]json.RawMessage)
236→	}
237→	return parsed, nil
238→}
