240→func ensureGitInfoExcludeContains(repoDir, entry string) error {
241→	excludePath := filepath.Join(repoDir, ".git", "info", "exclude")
242→
243→	data, err := os.ReadFile(excludePath)
244→	if err != nil && !errors.Is(err, os.ErrNotExist) {
245→		return fmt.Errorf("read %s: %w", excludePath, err)
246→	}
247→
248→	normalized := strings.ReplaceAll(string(data), "\r\n", "\n")
249→	for _, line := range strings.Split(normalized, "\n") {
250→		if strings.TrimSpace(line) == entry {
251→			return nil
252→		}
253→	}
254→
255→	var b strings.Builder
256→	if len(data) > 0 {
257→		b.Write(data)
258→		if data[len(data)-1] != '\n' {
259→			b.WriteByte('\n')
260→		}
261→	}
262→	b.WriteString(entry)
263→	b.WriteByte('\n')
264→
265→	if err := os.MkdirAll(filepath.Dir(excludePath), 0o755); err != nil {
266→		return fmt.Errorf("create %s: %w", filepath.Dir(excludePath), err)
267→	}
268→	if err := os.WriteFile(excludePath, []byte(b.String()), 0o644); err != nil {
269→		return fmt.Errorf("write %s: %w", excludePath, err)
270→	}
271→	return nil
272→}
