384→	s.ConsoleLog.WriteString("> " + out.Command + "\n")
385→	s.ConsoleLog.WriteString("stdout:\n" + out.Stdout + "\n")
386→	s.ConsoleLog.WriteString("stderr:\n" + out.Stderr + "\n")
387→}
