524→// CheckpointIDs lists all checkpoint IDs from the tree at the tip of the
525→// checkpoint branch. It parses the two-level directory structure
526→// ({prefix}/{suffix}/metadata.json) and returns the concatenated IDs.
527→func CheckpointIDs(t *testing.T, dir string) []string {
528→	t.Helper()
529→	out := gitOutputSafe(dir, "ls-tree", "-r", "--name-only", "entire/checkpoints/v1")
530→	if out == "" {
531→		return nil
532→	}
533→	seen := map[string]bool{}
534→	var ids []string
535→	for _, line := range strings.Split(strings.TrimSpace(out), "\n") {
536→		// Match {prefix}/{suffix}/metadata.json (top-level, not session-level)
537→		parts := strings.Split(line, "/")
538→		if len(parts) == 3 && parts[2] == "metadata.json" {
539→			id := parts[0] + parts[1]
540→			if !seen[id] {
541→				seen[id] = true
542→				ids = append(ids, id)
543→			}
544→		}
545→	}
546→	return ids
547→}
