585→// WaitForSessionMetadata polls until session metadata exists on the checkpoint
586→// branch for the given checkpoint ID and session index, then returns it.
587→// This handles the race where the checkpoint branch advances before session
588→// metadata is fully committed.
589→func WaitForSessionMetadata(t *testing.T, dir string, checkpointID string, sessionIndex int, timeout time.Duration) SessionMetadata {
590→	t.Helper()
591→
592→	path := fmt.Sprintf("%s/%d/metadata.json", CheckpointPath(checkpointID), sessionIndex)
593→	blob := "entire/checkpoints/v1:" + path
594→
595→	deadline := time.Now().Add(timeout)
596→	for time.Now().Before(deadline) {
597→		raw := gitOutputSafe(dir, "show", blob)
598→		if raw != "" {
599→			var meta SessionMetadata
600→			if err := json.Unmarshal([]byte(raw), &meta); err != nil {
601→				t.Fatalf("unmarshal session metadata from %s: %v", blob, err)
602→			}
603→			return meta
604→		}
605→		time.Sleep(500 * time.Millisecond)
606→	}
607→	t.Fatalf("session metadata %s did not appear within %s", blob, timeout)
608→	return SessionMetadata{}
609→}
