611→// SetupBareRemote creates a bare git repo, adds it as "origin", and pushes
612→// the initial commit. Returns the bare repo path.
613→func SetupBareRemote(t *testing.T, s *RepoState) string {
614→	t.Helper()
615→
616→	var bareDir string
617→	if os.Getenv("E2E_KEEP_REPOS") != "" {
618→		var err error
619→		bareDir, err = os.MkdirTemp("", "e2e-bare-*")
620→		if err != nil {
621→			t.Fatalf("create bare remote dir: %v", err)
622→		}
623→		t.Logf("E2E_KEEP_REPOS: bare remote will be preserved at %s", bareDir)
624→	} else {
625→		bareDir = t.TempDir()
626→	}
627→
628→	Git(t, bareDir, "init", "--bare")
