2096→// getStagedFiles returns a list of files staged for commit using native git CLI.
2097→// This is much faster than go-git's worktree.Status() which scans the entire
2098→// working tree. `git diff --cached --name-only` uses native git's optimized index
2099→// and filesystem monitors.
2100→//
2101→// Returns (non-nil empty slice, nil) when no files are staged — callers can
2102→// distinguish "no staged files" from "error resolving staged files" (nil, err).
2103→func getStagedFiles(ctx context.Context) ([]string, error) {
2104→	repoRoot, err := paths.WorktreeRoot(ctx)
2105→	if err != nil {
2106→		return nil, fmt.Errorf("resolve worktree root: %w", err)
2107→	}
2108→
2109→	cmd := exec.CommandContext(ctx, "git", "diff", "--cached", "--name-only")
2110→	cmd.Dir = repoRoot
2111→	output, err := cmd.Output()
2112→	if err != nil {
2113→		return nil, fmt.Errorf("git diff --cached: %w", err)
2114→	}
2115→
2116→	staged := []string{}
2117→	trimmed := strings.TrimSpace(string(output))
2118→	// Normalize Windows line endings (\r\n) to Unix (\n) for cross-platform git output
2119→	trimmed = strings.ReplaceAll(trimmed, "\r\n", "\n")
2120→	for _, line := range strings.Split(trimmed, "\n") {
2121→		if line != "" {
2122→			staged = append(staged, filepath.ToSlash(line))
2123→		}
2124→	}
2125→	return staged, nil
2126→}
